from pathlib import Path
program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        cells.add((yy, xx))
                        stack.append((yy, xx))
            objects.append((color, cells))
    # Pack components toward the right edge, resolving rightmost components first.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    placed = []
    for color, cells in objects:
        shift = 0
        while True:
            candidate = {(r, c + shift + 1) for r, c in cells}
            if any(c >= w for _, c in candidate):
                break
            if any(candidate & other for other_color, other in placed):
                break
            shift += 1
        moved = {(r, c + shift) for r, c in cells}
        placed.append((color, moved))
    out = [[0] * w for _ in range(h)]
    for color, cells in placed:
        for r, c in cells:
            out[r][c] = color
    return out
'''
prog.parent.mkdir(parents=True, exist_ok=True)
